"""Composition root (generated by G2C, A2C v1.4): the model and the other E2A seams, bound from
a profile with e2a.bindings. Nothing in this service constructs a model service by name.

The profile is E2A_PROVIDER_PROFILE, else 'simulated' (the request's a2c_sdlc.provider_profile).
E2A ships "simulated" (no account, no network). A provider package registered with E2A (its
entry point "e2a.providers") adds its own profiles; install it, then set E2A_PROVIDER_PROFILE.
"""
from functools import lru_cache

from e2a import Bindings, bindings_from_profile, resolve_config

from genai_assistant_service.tools.catalog import tools

DEFAULT_PROFILE = 'simulated'


@lru_cache(maxsize=1)
def bindings() -> Bindings:
    """The service's bindings, built once. verify=True refuses to start when the profile's
    required features are not provided by what it binds."""
    return bindings_from_profile(resolve_config("provider_profile", {}) or DEFAULT_PROFILE, verify=True)


def service_config(**extra) -> dict:
    """The config for workflow.execute() / agent.run(): the bound llm_service and engines, the
    profile's settings, and this service's tools."""
    return bindings().config(tools=tools(), **extra)
